INSERT INTO teaching_ready SELECT q.id FROM question q LEFT JOIN question_legal_subject s ON s.question_id=q.id JOIN teaching_proposal p ON p.id=q.id WHERE BINARY CAST(JSON_OBJECT('type',q.type,'stem',q.stem,'options',q.options,'answer',q.answer,'analysis',q.analysis,'category',q.category,'discipline',COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),'subject',COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)) AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND SHA2(CAST(JSON_ARRAY(q.type,q.stem,q.options,q.answer,q.analysis,q.category,COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)) AS CHAR),256)=p.expected_hash FOR UPDATE;
INSERT INTO question_content_revision (revision_key,question_id,before_content,after_content,evidence_urls) SELECT p.revision_key,p.id,p.before_content,p.after_content,p.evidence_urls FROM teaching_proposal p JOIN teaching_ready t ON t.id=p.id ON DUPLICATE KEY UPDATE revision_key=question_content_revision.revision_key;
INSERT INTO teaching_subject_change SELECT q.id,JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.discipline')),JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.subject')) FROM question q LEFT JOIN question_legal_subject s ON s.question_id=q.id JOIN teaching_proposal p ON p.id=q.id JOIN teaching_ready t ON t.id=q.id JOIN question_content_revision r ON r.revision_key=p.revision_key WHERE r.question_id=p.id AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(p.evidence_urls AS CHAR) AND BINARY CAST(JSON_OBJECT('type',q.type,'stem',q.stem,'options',q.options,'answer',q.answer,'analysis',q.analysis,'category',q.category,'discipline',COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),'subject',COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)) AS CHAR)=BINARY CAST(JSON_SET(p.after_content,'$.discipline',JSON_EXTRACT(p.before_content,'$.discipline'),'$.subject',JSON_EXTRACT(p.before_content,'$.subject')) AS CHAR);
INSERT INTO question_legal_subject (question_id,discipline,subject) SELECT question_id,discipline,subject FROM teaching_subject_change WHERE TRUE ON DUPLICATE KEY UPDATE discipline=VALUES(discipline),subject=VALUES(subject);
